void gemv(std::vector<double> const& A, std::vector<double> const& x, std::vector<double> &y, size_t M, size_t N) {
    // Validate dimensions and guard against overflow in M * N.
    if (N != 0 && M > std::numeric_limits<size_t>::max() / N) {
        throw std::invalid_argument("gemv: M * N overflows size_t");
    }
    const size_t requiredA = M * N;

    if (A.size() < requiredA) {
        throw std::invalid_argument("gemv: A.size() is smaller than M * N");
    }
    if (x.size() < N) {
        throw std::invalid_argument("gemv: x.size() is smaller than N");
    }

    // Handle aliasing safely: y may be the same object as A and/or x.
    const std::vector<double>* A_src = &A;
    const std::vector<double>* x_src = &x;
    std::vector<double> A_copy;
    std::vector<double> x_copy;

    if (&A == &y) {
        A_copy = A;
        A_src = &A_copy;
    }
    if (&x == &y) {
        x_copy = x;
        x_src = &x_copy;
    }

    y.resize(M);

    const double* a = A_src->data();
    const double* xv = x_src->data();

    // Use a signed index type for portable OpenMP loop control.
    if (M > static_cast<size_t>(std::numeric_limits<std::ptrdiff_t>::max()) ||
        N > static_cast<size_t>(std::numeric_limits<std::ptrdiff_t>::max())) {
        // Fallback for extremely large sizes that do not fit in ptrdiff_t.
        for (size_t i = 0; i < M; ++i) {
            double sum = 0.0;
            const size_t base = i * N;
            for (size_t j = 0; j < N; ++j) {
                sum += a[base + j] * xv[j];
            }
            y[i] = sum;
        }
        return;
    }

    const std::ptrdiff_t Mp = static_cast<std::ptrdiff_t>(M);
    const std::ptrdiff_t Np = static_cast<std::ptrdiff_t>(N);

    #pragma omp parallel for schedule(static)
    for (std::ptrdiff_t i = 0; i < Mp; ++i) {
        double sum = 0.0;
        const size_t base = static_cast<size_t>(i) * N;

        #pragma omp simd reduction(+:sum)
        for (std::ptrdiff_t j = 0; j < Np; ++j) {
            sum += a[base + static_cast<size_t>(j)] * xv[static_cast<size_t>(j)];
